jobs_terminal_finished_at_check.value:
(
        "jobs"."status" in ('completed', 'failed', 'cancelled') and "jobs"."finished_at" is not null
      ) or (
        "jobs"."status" not in ('completed', 'failed', 'cancelled') and "jobs"."finished_at" is null
      )

jobs_running_lease_check.value:
(
        "jobs"."status" = 'running' and "jobs"."lease_token" is not null
      ) or (
        "jobs"."status" <> 'running' and "jobs"."lease_token" is null
      )

run_effects_finished_shape_check.value:
(
        "run_effects"."status" = 'reserved' and "run_effects"."finished_at" is null
      ) or (
        "run_effects"."status" <> 'reserved' and "run_effects"."finished_at" is not null
      )

runs_terminal_finished_at_check.value:
(
        "runs"."status" in ('completed', 'failed', 'cancelled') and "runs"."finished_at" is not null
      ) or (
        "runs"."status" not in ('completed', 'failed', 'cancelled') and "runs"."finished_at" is null
      )
